const SUGGESTION_GENRES=[['all','Tous les genres'],[28,'Action'],[12,'Aventure'],[35,'Comédie'],[18,'Drame'],[14,'Fantastique'],[27,'Horreur'],[9648,'Mystère'],[10749,'Romance'],[878,'Science-fiction'],[53,'Thriller'],[16,'Animation']];
