document.addEventListener('submit',async e=>{if(e.target.id!=='mqListNameForm')return;e.preventDefault();const name=document.getElementById('listNameInput')?.value.trim();if(!name)return;state.lists=state.lists||{};if(listEditId==='new'){const id='list_'+Date.now();state.lists[id]={name,movieIds:[],tvIds:[],order:sortedLists().length};if(tab==='lists')listSelected=id}else if(state.lists[listEditId])state.lists[listEditId].name=name;listEditId=null;await persist();render()});
let draggedListId=null;
document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-drag-list]');if(!row)return;draggedListId=row.dataset.dragList;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',draggedListId);row.classList.add('is-dragging')});
document.addEventListener('dragover',e=>{const row=e.target.closest('[data-drag-list]');if(row&&draggedListId){e.preventDefault();e.dataTransfer.dropEffect='move'}});
document.addEventListener('drop',async e=>{const row=e.target.closest('[data-drag-list]');if(!row||!draggedListId)return;e.preventDefault();const dest=row.dataset.dragList;if(dest!==draggedListId){const ids=sortedLists().map(l=>l.id),from=ids.indexOf(draggedListId),to=ids.indexOf(dest);if(from>=0&&to>=0){ids.splice(from,1);ids.splice(to,0,draggedListId);ids.forEach((id,i)=>state.lists[id].order=i);await persist();render()}}draggedListId=null});
document.addEventListener('dragend',()=>{draggedListId=null;document.querySelectorAll('.is-dragging').forEach(el=>el.classList.remove('is-dragging'))});
function showPosterLightbox(path,title){
 if(!path)return;
 const current=filmCache.get(Number(film))||{};
 const gallery=[{path,label:'Affiche'}];
 if(current.backdrop_path&&current.backdrop_path!==path)gallery.push({path:current.backdrop_path,label:'Image du film'});
 for(const p of current.images?.posters||[])if(p.file_path&&!gallery.some(x=>x.path===p.file_path))gallery.push({path:p.file_path,label:'Affiche'});
 for(const p of current.images?.backdrops||[])if(p.file_path&&!gallery.some(x=>x.path===p.file_path))gallery.push({path:p.file_path,label:'Image du film'});
 let index=0;
 const dialog=document.createElement('dialog');dialog.className='mq-poster-lightbox';dialog.setAttribute('aria-label','Galerie de '+title);
 const image=document.createElement('img');image.alt='Affiche de '+title;
 const content=document.createElement('div');content.className='mq-lightbox-content';content.append(image);
 const close=document.createElement('button');close.type='button';close.className='mq-lightbox-close';close.textContent='×';close.setAttribute('aria-label','Fermer');close.addEventListener('click',()=>dialog.close());
 const counter=document.createElement('span');counter.className='mq-lightbox-counter';
 const previous=document.createElement('button');previous.className='mq-lightbox-previous';previous.type='button';previous.textContent='‹';previous.setAttribute('aria-label','Image précédente');
 const next=document.createElement('button');next.className='mq-lightbox-next';next.type='button';next.textContent='›';next.setAttribute('aria-label','Image suivante');
 const show=()=>{const item=gallery[index];image.src=poster(item.path,'original');image.alt=item.label+' de '+title;counter.textContent=(index+1)+' / '+gallery.length};
 previous.addEventListener('click',()=>{index=(index-1+gallery.length)%gallery.length;show()});
 next.addEventListener('click',()=>{index=(index+1)%gallery.length;show()});
 dialog.append(content,close);
 if(gallery.length>1)dialog.append(previous,next,counter);
 const onKey=e=>{if(e.key==='ArrowLeft'&&gallery.length>1){e.preventDefault();previous.click()}if(e.key==='ArrowRight'&&gallery.length>1){e.preventDefault();next.click()}};
 dialog.addEventListener('keydown',onKey);
 dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
 dialog.addEventListener('close',()=>dialog.remove(),{once:true});
 document.body.append(dialog);show();dialog.showModal()
}

document.addEventListener('click',e=>{const b=e.target.closest('[data-media-page]');if(!b)return;const step=Number(b.dataset.step)||0;if(b.dataset.mediaPage==='release')releasePage=Math.max(0,releasePage+step);else if(b.dataset.mediaPage==='upcoming')upcomingPage=Math.max(0,upcomingPage+step);else if(b.dataset.mediaPage==='current')currentPage=Math.max(0,currentPage+step);render()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-calendar-move],[data-calendar-today]');if(!b)return;if(b.hasAttribute('data-calendar-today'))releaseCalendarOffset=0;else releaseCalendarOffset=Math.max(-120,Math.min(120,releaseCalendarOffset+Number(b.dataset.calendarMove)));render()});
