document.addEventListener('change',async e=>{if(e.target.id==='releaseRole'){releaseRole=e.target.value;releasePerson='all';render();return}if(e.target.id==='releasePerson'){releasePerson=e.target.value;render();return}if(e.target.id==='accentColor'&&user){state.preferences={...(state.preferences||{}),accent:e.target.value};applyTheme();await persist();render()}});function updateFollowingResults(){const matching=followed().filter(p=>(followingRole==='all'||p.role===followingRole)&&p.name.toLocaleLowerCase('fr').includes(followingQuery.trim().toLocaleLowerCase('fr')));const target=document.getElementById('followingResults');if(target)target.innerHTML=personList(matching,followingView);const clear=document.getElementById('clearFollowingSearch');if(clear)clear.hidden=!followingQuery}

document.addEventListener('change',async e=>{if(e.target.matches('[data-tv-episode]')){await toggleEpisode(seriesId,Number(e.target.dataset.tvSeason),Number(e.target.dataset.tvEpisode))}});
document.addEventListener('change',e=>{if(e.target.id==='suggestionMinYear'||e.target.id==='suggestionMaxYear'){queueVisibleCount=24;suggestionPage=0;documentaryPage=0;render()}});
document.addEventListener('input',e=>{if(e.target.id==='suggestionMinYear'||e.target.id==='suggestionMaxYear'){if(e.target.id==='suggestionMinYear')suggestionMinYear=Math.min(Number(e.target.value),suggestionMaxYear);else suggestionMaxYear=Math.max(Number(e.target.value),suggestionMinYear);suggestionPage=0;document.getElementById(e.target.id==='suggestionMinYear'?'minYearOutput':'maxYearOutput').textContent=e.target.id==='suggestionMinYear'?suggestionMinYear:suggestionMaxYear;const bar=document.querySelector('.mq-range-selected');if(bar){bar.style.left=((suggestionMinYear-1900)/130*100)+'%';bar.style.right=(100-(suggestionMaxYear-1900)/130*100)+'%'}const counter=document.getElementById('mqFilterResultCount');if(counter)counter.textContent='les '+filteredResultCount()+' résultats';return}if(e.target.id==='listSearch'){listQuery=e.target.value;const target=document.getElementById('listResults');if(target){const all=sortedLists(),chosen=all.find(l=>l.id===listSelected),ids=chosen?(chosen.movieIds||[]):[...new Set(all.flatMap(l=>l.movieIds||[]))],tvIds=chosen?(chosen.tvIds||[]):[...new Set(all.flatMap(l=>l.tvIds||[]))];target.innerHTML=listTabMedia==='series'?seriesList(tvIds.map(id=>seriesCache.get(Number(id))||followedSeries().find(m=>m.id===Number(id))).filter(Boolean).filter(m=>matchesText(m.name,listQuery)),listView):filmList(ids.map(id=>filmCache.get(Number(id))).filter(Boolean).filter(m=>(listTabMedia==='documentaries'?!!bonusCategory(m):isFeatureFilm(m))&&matchesText(m.title,listQuery)),listView)}return}if(e.target.id==='seriesSearch'){seriesQuery=e.target.value;clearTimeout(seriesSearchTimer);seriesSearchTimer=setTimeout(searchSeries,350);const clear=e.target.parentElement.querySelector('.search-clear');if(clear)clear.hidden=!seriesQuery;return}if(['personFilmSearch','castSearch','nowSearch','releaseSearch','queueSearch'].includes(e.target.id)){const id=e.target.id;if(id==='personFilmSearch')personFilmQuery=e.target.value;else if(id==='castSearch')castQuery=e.target.value;else if(id==='nowSearch')nowQuery=e.target.value;else if(id==='releaseSearch')releaseQuery=e.target.value;else queueQuery=e.target.value;const clear=e.target.parentElement.querySelector('.search-clear');if(clear)clear.hidden=!e.target.value;updateFilterResults(id);return}if(e.target.id==='personSeriesSearch'){personSeriesQuery=e.target.value;updateFilterResults('personSeriesSearch');return}if(e.target.id==='followingSearch'){followingQuery=e.target.value;updateFollowingResults();return}if(e.target.id==='releasePersonSearch'){releasePerson=e.target.value.trim()||'all';const position=e.target.selectionStart;render();const input=document.getElementById('releasePersonSearch');input?.focus();input?.setSelectionRange(position,position);return}if(e.target.id==='search'){query=e.target.value;const clear=document.getElementById('clearExploreSearch');if(clear)clear.hidden=!query;clearTimeout(timer);timer=setTimeout(search,350)}});
async function openCard(target){if(!user)return;const scrollToDetailTop=()=>window.scrollTo({top:0,left:0,behavior:'instant'});if(target.dataset.openPerson){personFilmQuery='';selected=Number(target.dataset.openPerson);film=null;seriesId=null;personFilmRole='all';personMediaTab='films';render();const p=state.following[selected]||knownPeople.get(selected)||results.find(x=>x.id===selected)||currentPerson||{id:selected,role:'actor'};currentPerson=p;await loadPerson(p);await loadPersonSeries(p.id)}else if(target.dataset.openTv){seriesId=Number(target.dataset.openTv);selected=null;film=null;render();scrollToDetailTop();await loadSeries(seriesId);return}if(target.dataset.openFilm){castQuery='';film=Number(target.dataset.openFilm);selected=null;seriesId=null;if(!filmCache.get(film)?.credits){const d=await request('/api/movie/'+film);filmCache.set(film,d)}render();scrollToDetailTop()}}
document.addEventListener('click',async e=>{const calendar=e.target.closest('.mq-calendar-event[data-open-film],.mq-calendar-event[data-open-tv]');if(!calendar)return;e.preventDefault();e.stopImmediatePropagation();try{await openCard(calendar)}catch(err){error=err.message;render()}},true);
document.addEventListener('click',async e=>{if(e.target.closest('button:not(.stat-person-link),a,input,select,label'))return;const card=e.target.closest('[data-open-person],[data-open-film],[data-open-tv]');if(!card)return;try{await openCard(card)}catch(err){error=err.message;render()}});
document.addEventListener('keydown',async e=>{if(!['Enter',' '].includes(e.key)||e.target.closest('button,input,select'))return;const card=e.target.closest('[data-open-person],[data-open-film],[data-open-tv]');if(!card)return;e.preventDefault();try{await openCard(card)}catch(err){error=err.message;render()}});
function mainNavFocus(){document.querySelector('#mainNav button.active')?.focus()}
function applyTheme(){document.documentElement.style.setProperty('--accent',state.preferences?.accent||'#3bdd0e')}
async function restoreSavedView(){try{if(seriesId){await loadSeries(seriesId)}else if(film){const id=film;const m=await request('/api/movie/'+id);filmCache.set(id,m);if(film===id)render()}else if(selected){const id=selected;const p=state.following[id]||knownPeople.get(id)||{id,name:'Filmographie',role:'actor'};currentPerson=p;await loadPerson(p);await loadPersonSeries(id)}else if(tab==='now-playing')await loadNowPlaying();else if(tab==='series')await loadSeriesHome()}catch(e){error=e.message;render()}}
onAuthStateChanged(auth,u=>{authReady=!u;user=u;menuOpen=false;mobileNavOpen=false;unsub?.();unsub=null;state={following:{},statuses:{},dismissed:{},seenAt:{},preferences:{accent:'#3bdd0e'}};applyTheme();people.clear();knownPeople.clear();filmCache.clear();seriesCache.clear();seriesSeasonCache.clear();personSeriesCache.clear();restoredView=false;if(u){unsub=onSnapshot(doc(db,'users',u.uid,'data','movieQuest'),snap=>{if(snap.exists())state={following:{},statuses:{},dismissed:{},seenAt:{},series:{},lists:{},preferences:{accent:'#3bdd0e'},...snap.data()};applyTheme();authReady=true;if(!restoredView){restoredView=true;restoreSavedView()}if(tab==='explore'&&!selected&&!film&&!seriesId&&!document.body.classList.contains('app-booting')){for(const id of Object.keys(state.following))updateFollowControls(id);document.querySelectorAll('[data-follow]').forEach(b=>updateFollowControls(b.dataset.follow))}else if(selected&&!document.body.classList.contains('app-booting')){updateFollowControls(selected)}else render();loadFollowing();if(tab==='lists')hydrateListContent()},e=>{error=e.message;authReady=true;render()})}if(!u){render()}},e=>{error='Impossible de vérifier la session Google : '+e.message;user=null;authReady=true;render()});